"use client";
/* Generated by Antigravity AI - Adhering to SOLID & Design Patterns */

import { useAdminArticles } from "./useAdminArticles";
import { ArticleManagerToolbarComponent } from "./components/ArticleManagerToolbarComponent";
import { ArticleManagerTableComponent } from "./components/ArticleManagerTableComponent";
import { ArticleTrashModal } from "./modals/ArticleTrashModal";

export function ArticleManagerPage() {
  const manager = useAdminArticles();

  return (
    <div className="space-y-6">
      <ArticleManagerToolbarComponent
        search={manager.search}
        setSearch={manager.setSearch}
        statusFilter={manager.statusFilter}
        setStatusFilter={manager.setStatusFilter}
        categoryFilter={manager.categoryFilter}
        setCategoryFilter={manager.setCategoryFilter}
        sortFilter={manager.sortFilter}
        setSortFilter={manager.setSortFilter}
        isTrashMode={manager.isTrashMode}
        setIsTrashMode={manager.setIsTrashMode}
        handleEmptyTrash={manager.handleEmptyTrash}
        categories={manager.categories}
      />

      {!manager.isTrashMode && (
        <>
          <ArticleBulkActions
            selectedIds={manager.selectedIds}
            isTrash={false}
            handleBulkRestore={manager.handleBulkRestore}
            handleBulkDelete={manager.handleBulkDelete}
            handleBulkTrash={manager.handleBulkTrash}
          />
          <ArticleManagerTableComponent
            articles={manager.articles}
            selectedIds={manager.selectedIds}
            toggleSelectAll={manager.toggleSelectAll}
            toggleSelect={manager.toggleSelect}
            handlePinToggle={manager.handlePinToggle}
            handleDelete={manager.handleDelete}
            handleRestore={manager.handleRestore}
            isTrash={false}
            loading={manager.loading}
          />
        </>
      )}

      <ArticleTrashModal
        isOpen={manager.isTrashMode}
        setIsOpen={manager.setIsTrashMode}
        articles={manager.articles}
        selectedIds={manager.selectedIds}
        toggleSelectAll={manager.toggleSelectAll}
        toggleSelect={manager.toggleSelect}
        handlePinToggle={manager.handlePinToggle}
        handleDelete={manager.handleDelete}
        handleRestore={manager.handleRestore}
        handleBulkRestore={manager.handleBulkRestore}
        handleBulkDelete={manager.handleBulkDelete}
        handleBulkTrash={manager.handleBulkTrash}
        loading={manager.loading}
      />
    </div>
  );
}

interface ArticlesBulkActionsProps {
  selectedIds: string[];
  isTrash: boolean;
  handleBulkRestore: () => void;
  handleBulkDelete: () => void;
  handleBulkTrash: () => void;
}

export function ArticleBulkActions({
  selectedIds,
  isTrash,
  handleBulkRestore,
  handleBulkDelete,
  handleBulkTrash,
}: ArticlesBulkActionsProps) {
  if (selectedIds.length === 0) return null;

  return (
    <div className="bg-blue-50 dark:bg-blue-900/30 border border-blue-100 dark:border-blue-800 p-3 rounded-xl flex items-center justify-between animate-fadeIn mb-6">
      <span className="text-sm font-medium text-blue-700 dark:text-blue-400">
        Đã chọn {selectedIds.length} bài viết
      </span>
      <div className="flex gap-2">
        {isTrash ? (
          <>
            <button
              onClick={handleBulkRestore}
              className="px-3 py-1.5 bg-white dark:bg-slate-800 text-green-600 dark:text-green-400 text-sm font-medium rounded-lg shadow-sm border border-gray-200 dark:border-slate-700 hover:bg-green-50 transition-colors"
            >
              Khôi phục
            </button>
            <button
              onClick={handleBulkDelete}
              className="px-3 py-1.5 bg-white dark:bg-slate-800 text-red-600 dark:text-red-400 text-sm font-medium rounded-lg shadow-sm border border-gray-200 dark:border-slate-700 hover:bg-red-50 transition-colors"
            >
              Xóa vĩnh viễn
            </button>
          </>
        ) : (
          <button
            onClick={handleBulkTrash}
            className="px-3 py-1.5 bg-white dark:bg-slate-800 text-red-600 dark:text-red-400 text-sm font-medium rounded-lg shadow-sm border border-gray-200 dark:border-slate-700 hover:bg-red-50 transition-colors"
          >
            Chuyển vào thùng rác
          </button>
        )}
      </div>
    </div>
  );
}

export { ArticleManagerPage as ArticlesListPage };


